const ModulesList = () => {
  const [modules, setModules] = useState([]);
  const [filteredModules, setFilteredModules] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [sortBy, setSortBy] = useState('name');

  useEffect(() => {
    // Fetch modules from API
    fetchModules().then(setModules);
  }, []);

  useEffect(() => {
    let result = [...modules];

    // Apply search filter
    if (searchQuery) {
      result = result.filter(module => 
        module.name.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Apply status filter
    if (statusFilter !== 'all') {
      result = result.filter(module => module.status === statusFilter);
    }

    // Apply sorting
    result.sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'recent') return b.lastAccessed - a.lastAccessed;
      if (sortBy === 'popular') return b.accessCount - a.accessCount;
      return 0;
    });

    setFilteredModules(result);
  }, [modules, searchQuery, statusFilter, sortBy]);

  return (
    <div>
      <SearchAndFilter 
        onSearch={setSearchQuery}
        onFilter={setStatusFilter}
        onSort={setSortBy}
      />
      <ModulesGrid modules={filteredModules} />
    </div>
  );
};
```

