// services/activityService.ts
import { supabase } from '../lib/supabaseClient';

export const fetchRecentActivities = async (userId: string) => {
  const { data, error } = await supabase
    .from('user_activities')
    .select('id, module_id, module_name, timestamp, action_type')
    .eq('user_id', userId)
    .order('timestamp', { ascending: false })
    .limit(5);

  if (error) throw error;
  return data;
};

export const fetchFavoriteModules = async (userId: string) => {
  const { data, error } = await supabase
    .from('user_module_stats')
    .select('id, module_id, module_name, access_count')
    .eq('user_id', userId)
    .order('access_count', { ascending: false })
    .limit(3);

  if (error) throw error;
  return data;
};

export const fetchSuggestions = async (userId: string) => {
  // Lógica para buscar sugestões baseadas no perfil do usuário
  // Pode incluir módulos populares que o usuário ainda não acessou
  // ou módulos relacionados aos interesses do usuário

  const { data, error } = await supabase
    .from('module_suggestions')
    .select('id, module_id, module_name, reason')
    .eq('user_id', userId)
    .limit(3);

  if (error) throw error;
  return data;
};
```

