```tsx
import { useState, useEffect } from 'react';
import { fetchRecentActivities, fetchFavoriteModules, fetchSuggestions } from '../services/activityService';
import { Timeline, TimelineItem, TimelineIcon } from './Timeline';
import { ModuleCard, ModuleItem } from './ModuleCard';
import { formatDate } from '../utils/dateUtils';
import { Skeleton } from './ui/skeleton';

const RecentActivity = () => {
  const [recentActivities, setRecentActivities] = useState([]);
  const [favoriteModules, setFavoriteModules] = useState([]);
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const userId = 'current-user-id'; // Obter do contexto de autenticação
    setLoading(true);

    Promise.all([
      fetchRecentActivities(userId),
      fetchFavoriteModules(userId),
      fetchSuggestions(userId)
    ])
      .then(([activities, favorites, userSuggestions]) => {
        setRecentActivities(activities);
        setFavoriteModules(favorites);
        setSuggestions(userSuggestions);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching activity data:', err);
        setError('Não foi possível carregar os dados de atividade');
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <Skeleton className="h-80 rounded-lg" />
        <div className="space-y-6">
          <Skeleton className="h-36 rounded-lg" />
          <Skeleton className="h-36 rounded-lg" />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-red-50 border border-red-200 rounded-lg text-red-700">
        {error}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
      <ModuleCard title="Atividade Recente">
        {recentActivities.length > 0 ? (
          <Timeline>
            {recentActivities.map((activity) => (
              <TimelineItem key={activity.id}>
                <p className="font-medium">{activity.module_name}</p>
                <p className="text-sm text-gray-500">{formatDate(activity.timestamp)}</p>
              </TimelineItem>
            ))}
          </Timeline>
        ) : (
          <p className="text-gray-500">Nenhuma atividade recente encontrada.</p>
        )}
      </ModuleCard>

      <div className="space-y-6">
        <ModuleCard title="Módulos Favoritos">
          {favoriteModules.length > 0 ? (
            <div className="space-y-2">
              {favoriteModules.map((module) => (
                <ModuleItem 
                  key={module.id}
                  name={module.module_name}
                  subtitle={`${module.access_count} acessos`}
                  iconColor="#0A2342"
                />
              ))}
            </div>
          ) : (
            <p className="text-gray-500">Nenhum módulo favorito encontrado.</p>
          )}
        </ModuleCard>

        <ModuleCard title="Sugestões para Você">
          {suggestions.length > 0 ? (
            <div className="space-y-2">
              {suggestions.map((suggestion) => (
                <ModuleItem 
                  key={suggestion.id}
                  name={suggestion.module_name}
                  subtitle={suggestion.reason}
                  iconColor="#14B8A6"
                  textColor="#134E4A"
                />
              ))}
            </div>
          ) : (
            <p className="text-gray-500">Nenhuma sugestão disponível no momento.</p>
          )}
        </ModuleCard>
      </div>
    </div>
  );
};

export default RecentActivity;
```

Implementar também uma função de utilidade para formatação de datas:

```tsx
// utils/dateUtils.ts
export const formatDate = (dateString: string) => {
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.round(diffMs / 60000);
  const diffHours = Math.round(diffMins / 60);
  const diffDays = Math.round(diffHours / 24);

  if (diffMins < 60) {
    return `${diffMins} min atrás`;
  } else if (diffHours < 24) {
    return `${diffHours} h atrás`;
  } else if (diffDays < 7) {
    return `${diffDays} dias atrás`;
  } else {
    return date.toLocaleDateString('pt-BR');
  }
};
```

