export const useModules = () => {
  const [modules, setModules] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadModules = async () => {
      try {
        setLoading(true);
        const data = await fetchModules();
        setModules(data);
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
